export async function createScene(engine, canvas, BABYLON) {
  console.clear();
  const scene = new BABYLON.Scene(engine);
  scene.clearColor = BABYLON.Color4.FromHexString("#312728FF");
  scene.useRightHandedSystem = true;

  var camera = new BABYLON.ArcRotateCamera("camera", BABYLON.Tools.ToRadians(90), BABYLON.Tools.ToRadians(65), 10, BABYLON.Vector3.Zero(), scene);
  camera.setTarget(new BABYLON.Vector3(55.37, 1.14, -3.54));
  camera.alpha = 1.543;
  camera.beta = 1.466;
  camera.radius = 300;
  camera.inertia = 0.4;
  camera.wheelDeltaPercentage = 0.3;
  camera.panningSensibility = 10000;
  camera.minZ = 0.01;
  camera.maxZ = 10000;
  camera.attachControl(canvas, true);

  var light = new BABYLON.HemisphericLight("light", new BABYLON.Vector3(0, -0.09, -1), scene);

  const hdrTexture = BABYLON.CubeTexture.CreateFromPrefilteredData("https://assets.babylonjs.com/textures/environment.env", scene);
  scene.environmentTexture = hdrTexture;

  var fontData = await (await fetch("https://assets.babylonjs.com/fonts/Kenney Future Regular.json")).json();

  function createTextMesh(text) {
    const letters = new BABYLON.Mesh("letters_" + text);

    const letterMeshes = [];
    const step = 1 / text.length;

    for (let i = 0; i < text.length; i++) {
      let letterMesh = BABYLON.MeshBuilder.CreateText(
        `letter${i}`,
        text[i],
        fontData,
        {
          size: 16,
          resolution: 64,
          depth: 10,
          perLetterFaceUV: (index) => {
            const startX = index * step;
            return [
              new BABYLON.Vector4(0, 0, 1, 1),
              new BABYLON.Vector4(startX, 0, startX + step, 1),
              new BABYLON.Vector4(startX, 0, startX + step, 1),
            ];
          },
        },
        scene
      );

      letterMesh.position.x = i * 20;
      letterMeshes.push(letterMesh);

      letterMesh.setParent(letters);
    }

    return letters;
  }

  const textMaterial = new BABYLON.PBRMaterial("mat", scene);
  textMaterial.albedoColor = new BABYLON.Color3(1, 0.53, 0);
  textMaterial.backFaceCulling = false;
  textMaterial.metallic = 0.2;
  textMaterial.roughness = 0.05;
  textMaterial.specularIntensity = 1.15;
  textMaterial.reflectionTexture = hdrTexture;
  textMaterial.environmentIntensity = 1.2;

  const textMaterial2 = new BABYLON.PBRMaterial("mat2", scene);
  textMaterial2.albedoColor = new BABYLON.Color3(0, 0.85, 1);
  textMaterial2.backFaceCulling = false;
  textMaterial2.metallic = 0.2;
  textMaterial2.roughness = 0.05;
  textMaterial2.specularIntensity = 1.15;
  textMaterial2.reflectionTexture = hdrTexture;
  textMaterial2.environmentIntensity = 1.2;

  function animateLetters(letterMeshes, scene) {
    letterMeshes.getChildMeshes().forEach((mesh, i) => {
      const animation = new BABYLON.Animation(
        `scaleAnimation${i}`,
        "scaling",
        30, // FPS
        BABYLON.Animation.ANIMATIONTYPE_VECTOR3,
        BABYLON.Animation.ANIMATIONLOOPMODE_CYCLE
      );

      const keys = [
        { frame: 0, value: new BABYLON.Vector3(1, 1, 1) },
        { frame: 10, value: new BABYLON.Vector3(1.2, 1.2, 1.2) },
        { frame: 20, value: new BABYLON.Vector3(1, 1, 1) },
        { frame: 30, value: new BABYLON.Vector3(1, 1, 1) },
      ];

      animation.setKeys(keys);
      mesh.animations.push(animation);

      setTimeout(() => {
        scene.beginAnimation(mesh, 0, 30, true);
      }, i * 300);
    });
  }

  var myText = createTextMesh("WAVY");
  myText.position.x = -30;
  myText.getChildMeshes().forEach((m) => (m.position.y = 0));
  animateLetters(myText, scene);

  var myText2 = createTextMesh("EFFECT");
  myText2.position.x = 60;
  myText2.getChildMeshes().forEach((m) => (m.position.y = 0));
  animateLetters(myText2, scene);

  myText.getChildMeshes().forEach((m) => (m.material = textMaterial));
  myText2.getChildMeshes().forEach((m) => (m.material = textMaterial2));

  return scene;
}
